CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admins (id INTEGER PRIMARY KEY CHECK(id=1), username TEXT NOT NULL, password TEXT NOT NULL, version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>0), available INTEGER NOT NULL, featured INTEGER NOT NULL, deleted INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS images (id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), filename TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS quotes (token TEXT PRIMARY KEY, items TEXT NOT NULL, total INTEGER NOT NULL, created INTEGER NOT NULL, order_id TEXT);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, created TEXT NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT NOT NULL, recipient TEXT NOT NULL, address TEXT NOT NULL, city TEXT NOT NULL, postcode TEXT NOT NULL, delivery_date TEXT NOT NULL, message TEXT NOT NULL, utr TEXT UNIQUE NOT NULL, items TEXT NOT NULL, total INTEGER NOT NULL, payment TEXT NOT NULL, status TEXT NOT NULL, internal_note TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS orders_phone ON orders(phone,created);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), happened TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS enquiries (id INTEGER PRIMARY KEY, created TEXT NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, message TEXT NOT NULL, order_ref TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'New');
CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY, name TEXT NOT NULL, review TEXT NOT NULL, stars INTEGER NOT NULL CHECK(stars BETWEEN 1 AND 5), photo TEXT DEFAULT '', visible INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS attempts (scope TEXT NOT NULL, address TEXT NOT NULL, at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS attempts_recent ON attempts(scope,address,at);
